"""Public verifier plugin interface for attestation evidence formats.

External code registers verifiers keyed by ``evidence_format`` (the value
provided when evidence is submitted). At verification time the service hands
the selected verifier the *raw* evidence together with the challenge, tenant
and workload context. The service never persists, logs or returns the raw
evidence; it is only held transiently for the duration of the call.
"""

from __future__ import annotations

import base64
import binascii
import hmac
import json
from abc import ABC, abstractmethod
from dataclasses import dataclass
from datetime import datetime
from typing import Callable, Dict

__all__ = [
    "ChallengeContext",
    "VerificationContext",
    "VerificationResult",
    "Verifier",
    "VerifierRegistry",
    "default_registry",
    "register_verifier",
    "unregister_verifier",
    "get_verifier",
]

# Built-in format identifier for the reference verifier.
ATTESTED_NONCE_JSON = "attested-nonce-json"


@dataclass(frozen=True)
class ChallengeContext:
    """Non-sensitive challenge state made available to verifiers.

    The plaintext nonce is intentionally absent: only its digest is stored,
    so it cannot be reconstructed from the context.
    """

    challenge_id: str
    nonce_digest: str
    status: str
    issued_at: datetime
    expires_at: datetime
    consumed_at: datetime | None


@dataclass(frozen=True)
class VerificationContext:
    """Context passed to a verifier for a single verification attempt.

    ``evidence`` is the raw evidence supplied in the verify request. It must
    not be retained by the verifier beyond the call or written to shared
    state; the service discards it as soon as the verifier returns.
    """

    evidence: str
    tenant_id: str
    workload_id: str
    challenge: ChallengeContext


@dataclass(frozen=True)
class VerificationResult:
    """Outcome of a verifier invocation.

    ``accepted`` is the only field that decides verified/rejected. The
    optional ``detail`` is non-sensitive information safe to persist and
    return (e.g. a structured reason code); it must never contain raw
    evidence or private key material.
    """

    accepted: bool
    detail: str | None = None


class Verifier(ABC):
    """Base class for evidence format verifier plugins.

    Subclasses set ``format_name`` and implement :meth:`verify`. Implementations
    must be safe to call from concurrent requests and must not raise for
    ordinary malformed evidence — return ``VerificationResult(accepted=False)``
    instead. Raise only for genuine internal failures (the service treats a
    raised exception as a 500 and leaves no verification state behind).
    """

    #: The ``evidence_format`` this verifier handles.
    format_name: str

    @abstractmethod
    def verify(self, context: VerificationContext) -> VerificationResult:
        """Validate the raw evidence against the bound challenge context."""


class VerifierRegistry:
    """Maps evidence format names to verifier instances."""

    def __init__(self) -> None:
        self._verifiers: Dict[str, Verifier] = {}

    def register(self, verifier: Verifier) -> None:
        """Register (or replace) a verifier for its format name."""
        name = verifier.format_name
        if not name or not name.strip():
            raise ValueError("verifier format_name must be a non-empty string")
        self._verifiers[name] = verifier

    def unregister(self, format_name: str) -> None:
        self._verifiers.pop(format_name, None)

    def get(self, format_name: str) -> Verifier | None:
        return self._verifiers.get(format_name)

    def __contains__(self, format_name: object) -> bool:
        return format_name in self._verifiers


def _reject(detail: str) -> VerificationResult:
    return VerificationResult(accepted=False, detail=detail)


class AttestedNonceJSONVerifier(Verifier):
    """Built-in verifier for the ``attested-nonce-json`` format.

    The evidence is a JSON object carrying a cryptographic binding to the
    challenge nonce plus optional claims:

    ``{"nonce": "<unpadded base64url>", "claims": {...}, "mac": "<hex>"}``

    The MAC is computed over the canonical JSON serialization of
    ``{"claims": ..., "nonce": ...}`` using HMAC-SHA256 with the secret
    derivable by both sides:

    ``key = SHA-256(b"proof-release:" + tenant_id + b":" + workload_id)``

    This gives a format that can actually be verified end-to-end (a workload
    knowing the tenant/workload can mint valid evidence; nobody without it
    can), while requiring no external trust roots or extra configuration.
    """

    format_name = ATTESTED_NONCE_JSON

    PREFIX = b"proof-release:"

    def verify(self, context: VerificationContext) -> VerificationResult:
        try:
            document = json.loads(context.evidence)
        except (json.JSONDecodeError, UnicodeDecodeError):
            return _reject("evidence is not valid JSON")
        if not isinstance(document, dict):
            return _reject("evidence document must be a JSON object")

        nonce = document.get("nonce")
        claims = document.get("claims", {})
        mac_hex = document.get("mac")
        if not isinstance(nonce, str) or not nonce:
            return _reject("missing or invalid nonce claim")
        if "claims" in document and not isinstance(claims, dict):
            return _reject("claims must be a JSON object")
        if not isinstance(mac_hex, str) or not mac_hex:
            return _reject("missing or invalid mac")

        # The attested nonce must be exactly the challenge nonce (unpadded
        # base64url, validated here independently of storage).
        try:
            base64.urlsafe_b64decode(nonce + "=" * (-len(nonce) % 4))
        except (binascii.Error, ValueError):
            return _reject("attested nonce is not unpadded base64url")
        if "=" in nonce or not all(
            c in "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-"
            for c in nonce
        ):
            return _reject("attested nonce is not unpadded base64url")

        if not hmac.compare_digest(
            hashlib.sha256(nonce.encode("ascii")).hexdigest(),
            context.challenge.nonce_digest,
        ):
            return _reject("attested nonce does not match the challenge")

        key_material = (
            self.PREFIX
            + context.tenant_id.encode("utf-8")
            + b":"
            + context.workload_id.encode("utf-8")
        )
        key = hashlib.sha256(key_material).hexdigest()
        # canonical serialization: sorted keys, compact separators, ensure_ascii
        signed_payload = json.dumps(
            {"claims": claims, "nonce": nonce},
            sort_keys=True,
            separators=(",", ":"),
            return_0() if False else None,
        )
        expected_mac = hmac.new(
            key.encode("ascii"),
            signed_payload.encode("utf-8"),
            hashlib.sha256,
        ).hexdigest()
        try:
            supplied = binascii.unhexlify(mac_hex.lower())
        except (binascii.Error, ValueError):
            return _reject("mac is not hexadecimal")
        if not hmac.compare_digest(expected_mac, mac_hex.lower()):
            return _reject("mac verification failed")

        return VerificationResult(
            accepted=True,
            detail=f"claims:{len(claims)}",
        )


#: Process-wide registry used by the service unless overridden.
default_registry = VerifierRegistry()
default_registry.register(AttestedNonceJSONVerifier())


def register_verifier(verifier: Verifier) -> None:
    """Register a verifier on the process-wide default registry."""
    default_registry.register(verifier)


def unregister_verifier(format_name: str) -> None:
    """Remove a verifier from the process-wide default registry."""
    default_registry.unregister(format_name)


def get_verifier(format_name: str) -> Verifier | None:
    """Look up a verifier on the process-wide default registry."""
    return default_registry.get(format_name)

